const http = require('http');
const fs = require('fs');
const path = require('path');

const url = 'http://127.0.0.1:63958/status';

http.get(url, (res) => {
  const outDir = path.join(__dirname, 'results');
  fs.mkdirSync(outDir, { recursive: true });
  const outFile = path.join(outDir, 'status.json');
  fs.writeFileSync(outFile, JSON.stringify({ status: res.statusCode }) + '\n');
  console.log(`status=${res.statusCode} written to ${outFile}`);
  res.resume();
}).on('error', (err) => {
  console.error(`Request failed: ${err.message}`);
  process.exit(1);
});

